static String buildMavenLocalPath(String groupId, String artifactId, String version) {
    return groupId.replace('.', '/') + '/' + artifactId + '/' + version + '/';
}
System.out.println(buildMavenLocalPath("com.example","lib","1.0.0"));

static boolean isValidGav(String g, String a, String v) {
    return g != null && g.contains('.') && a != null && !a.contains(' ') && v != null && !v.isBlank();
}
System.out.println(isValidGav("com.example","lib","1.0.0"));
System.out.println(isValidGav("example","my lib",""));

static String previewGeneratedPom(String g, String a, String v, List<String> deps) {
    StringBuilder sb = new StringBuilder("<project><groupId>"+g+"</groupId><artifactId>"+a+"</artifactId><version>"+v+"</version><dependencies>\n");
    for (String d : deps) sb.append("  <dependency>").append(d).append("</dependency>\n");
    sb.append("</dependencies></project>");
    return sb.toString();
}
System.out.println(previewGeneratedPom("com.example","lib","1.0.0", List.of("gson")));

static List<String> selectPublishTargets(boolean isSnapshot, boolean isCi) {
    if (!isCi) return List.of("mavenLocal");
    return isSnapshot ? List.of("snapshots-repo") : List.of("releases-repo");
}
for (boolean s : new boolean[]{true,false}) for (boolean c : new boolean[]{true,false})
    System.out.println("snapshot="+s+" ci="+c+" -> "+selectPublishTargets(s,c));

