static String computeVersion(String base, boolean release, String buildNum) {
    if (release) return base;
    String v = base + "-SNAPSHOT";
    return buildNum != null ? v + "+build." + buildNum : v;
}
System.out.println(computeVersion("1.2.0", true, null));
System.out.println(computeVersion("1.2.0", false, "42"));

