static boolean validateCredentialsBeforePublish(String user, String pass) {
    if (user == null || pass == null) { System.out.println("BLAD: brak credentials"); return false; }
    if (pass.length() < 8) { System.out.println("BLAD: haslo za krotkie"); return false; }
    return true;
}

record PublishedArtifact(String groupId, String artifactId, String version, long timestamp) {}
static PublishedArtifact findLatestRelease(List<PublishedArtifact> artifacts) {
    return artifacts.stream().filter(a -> !a.version().contains("SNAPSHOT")).max(Comparator.comparingLong(PublishedArtifact::timestamp)).orElse(null);
}

static boolean wouldOverwriteExisting(String version, boolean targetIsRelease, Set<String> existing) {
    return targetIsRelease && existing.contains(version);
}
System.out.println(wouldOverwriteExisting("1.0.0", true, Set.of("1.0.0")));
System.out.println(wouldOverwriteExisting("1.0.0-SNAPSHOT", false, Set.of("1.0.0-SNAPSHOT")));

static String mapToPomScope(String configuration) {
    return switch (configuration) {
        case "implementation", "api" -> "compile";
        case "runtimeOnly" -> "runtime";
        case "testImplementation" -> null;
        default -> "compile";
    };
}
System.out.println(mapToPomScope("implementation"));
System.out.println(mapToPomScope("testImplementation"));

static void publishIfReady(boolean checklistPassed, String version) {
    if (!checklistPassed) { System.out.println("ODMOWA: checklist nie przeszedl"); return; }
    if (version.contains("SNAPSHOT")) { System.out.println("ODMOWA: wersja SNAPSHOT nie jest release'em"); return; }
    System.out.println("PUBLIKUJE wersje " + version);
}

